              if grid[r][c] != bg and (r, c) not in bar_cells]
    fill = grid[points[0][0]][points[0][1]] if points else bg

    # The bars project their inner half into the grid.
    for r, a, b, _ in bars:
        mid = (a + b) // 2
        if r == 0:
            cols, rows = range(mid, b), range(1, h)
        else:
